"use client";

/**
 * ChoiceCards. Choosing between things that need more than a word: a plan,
 * a template, an account. Each option is a card (title, a line, anything
 * else: a price, a preview) and the whole card is the choice. The chosen one
 * lights a rail along its edge and its pip; nothing else about it changes
 * colour, so one accent still means one thing.
 *
 * One choice is a radio group (arrow keys move and choose, one tab stop);
 * `multiple` is a group of checkboxes. Base UI RadioGroup/Radio and
 * CheckboxGroup/Checkbox own the roles, keys and value.
 */
import { forwardRef, useId, type ReactNode } from "react";
import type { EchoInterop } from "echo-ui-core/types";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { CheckboxGroup as BaseCheckboxGroup } from "@base-ui/react/checkbox-group";
import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import { useSoundOptional } from "echo-ui-core/sound";
import "../panel/panel.css";
import "./choice-cards.css";

export interface ChoiceCard {
  value: string;
  title: string;
  description?: ReactNode;
  /** Anything else on the card: a price, a preview, a badge. */
  extra?: ReactNode;
  disabled?: boolean;
}

interface ChoiceCardsOwnProps extends EchoInterop {
  /** The group's name, shown above it. */
  label: string;
  options: ChoiceCard[];
  /** Several at once (checkboxes). Default: one (radios). */
  multiple?: boolean;
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  /** Minimum card width before they wrap. Default "14rem". */
  minCardWidth?: string;
}

const Tick = () => (
  <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M3.5 8.5l3 3 6-7" />
  </svg>
);

export type ChoiceCardsProps = ChoiceCardsOwnProps;

/** `forwardRef` — see the note on `Field`. The ref lands on the group. */
export const ChoiceCards = forwardRef<HTMLDivElement, ChoiceCardsProps>(function ChoiceCards(
  { label, options, multiple = false, value, defaultValue, onValueChange, name, minCardWidth = "14rem", id: _id, disabled, ...interop },
  ref,
) {
  const id = useId();
  const sound = useSoundOptional();
  const face = (o: ChoiceCard) => (
    <>
      <span className="echo-choice-cards__mark" aria-hidden="true">
        {multiple ? (
          <BaseCheckbox.Indicator className="echo-choice-cards__tick">
            <Tick />
          </BaseCheckbox.Indicator>
        ) : (
          <BaseRadio.Indicator className="echo-choice-cards__pip" />
        )}
      </span>
      <span className="echo-choice-cards__text">
        <span className="echo-choice-cards__title">{o.title}</span>
        {o.description ? <span className="echo-choice-cards__description">{o.description}</span> : null}
        {o.extra ? <span className="echo-choice-cards__extra">{o.extra}</span> : null}
      </span>
    </>
  );
  const grid = { gridTemplateColumns: `repeat(auto-fill, minmax(min(${minCardWidth}, 100%), 1fr))` };
  const heading = (
    <span id={`${id}-name`} className="echo-choice-cards__name">
      {label}
    </span>
  );
  const changed = (next: unknown) => {
    sound?.play("select");
    onValueChange?.(next as string | string[]);
  };

  if (multiple) {
    return (
      <div className="echo-choice-cards">
        {heading}
        <BaseCheckboxGroup
          ref={ref}
          className="echo-choice-cards__grid"
          {...interop}
          {...(disabled !== undefined ? { disabled } : {})}
          style={grid}
          aria-labelledby={`${id}-name`}
          {...(value !== undefined ? { value: value as string[] } : {})}
          {...(defaultValue !== undefined ? { defaultValue: defaultValue as string[] } : {})}
          onValueChange={changed}
        >
          {options.map((o) => (
            <BaseCheckbox.Root
              key={o.value}
              value={o.value}
              className="echo-panel echo-choice-cards__card"
              data-variant="raised"
              {...(name ? { name } : {})}
              {...(o.disabled ? { disabled: true } : {})}
            >
              {face(o)}
            </BaseCheckbox.Root>
          ))}
        </BaseCheckboxGroup>
      </div>
    );
  }
  return (
    <div className="echo-choice-cards">
      {heading}
      <BaseRadioGroup
        ref={ref}
        className="echo-choice-cards__grid"
        {...interop}
        {...(disabled !== undefined ? { disabled } : {})}
        style={grid}
        aria-labelledby={`${id}-name`}
        {...(value !== undefined ? { value } : {})}
        {...(defaultValue !== undefined ? { defaultValue } : {})}
        {...(name ? { name } : {})}
        onValueChange={changed}
      >
        {options.map((o) => (
          <BaseRadio.Root
            key={o.value}
            value={o.value}
            className="echo-panel echo-choice-cards__card"
            data-variant="raised"
            {...(o.disabled ? { disabled: true } : {})}
          >
            {face(o)}
          </BaseRadio.Root>
        ))}
      </BaseRadioGroup>
    </div>
  );
});

/**
 * ChoiceCards. Panels as options: a pip (or a tick) in a hole at the start,
 * the words beside it. The chosen card lights a rail along its start edge and
 * its mark; the card itself stays plastic.
 */
.echo-choice-cards {
  display: grid;
  gap: var(--echo-space-5);
  min-width: 0;
}
.echo-choice-cards__name {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}
.echo-choice-cards__grid {
  display: grid;
  gap: var(--echo-space-6);
}
.echo-choice-cards__card {
  display: flex;
  align-items: flex-start;
  gap: var(--echo-space-6);
  box-sizing: border-box;
  width: 100%;
  padding: var(--echo-space-8);
  border: 0;
  cursor: pointer;
  text-align: start;
  color: var(--echo-text);
  font: inherit;
  transition:
    transform var(--echo-duration-tick) ease,
    box-shadow var(--echo-duration-swap) ease;
}
@media (hover: hover) {
  .echo-choice-cards__card:hover {
    box-shadow: var(
      --echo-shadow-lifted,
      0 1px 0 rgb(255 255 255 / calc(0.07 * var(--echo-gloss, 1))),
      0 10px 22px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.45 * var(--echo-shade, 1) * 100%), transparent)
    );
  }
}
.echo-choice-cards__card:active {
  transform: translateY(1px);
}
/* Chosen: the lit rail along the start edge (an inset, inside the radius). */
.echo-choice-cards__card:is([data-checked]) {
  box-shadow:
    inset var(--echo-border-heavy, 4px) 0 0 var(--echo-accent-glow),
    0 6px 14px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-choice-cards__card:is([data-checked]):dir(rtl) {
  box-shadow:
    inset calc(-1 * var(--echo-border-heavy, 4px)) 0 0 var(--echo-accent-glow),
    0 6px 14px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-choice-cards__card:focus-visible {
  outline: 2px solid var(--echo-accent-ink, var(--echo-accent-glow));
  outline-offset: 3px;
}
.echo-choice-cards__card[data-disabled] {
  cursor: default;
  opacity: 0.45;
}
/* The mark: a hole, with a pip or a tick when chosen. */
.echo-choice-cards__mark {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-well);
  box-shadow: inset 0 2px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-choice-cards__pip {
  width: 10px;
  height: 10px;
  border-radius: var(--echo-radius-full);
  background: linear-gradient(180deg, var(--echo-primary-cap-top), var(--echo-primary-cap-base));
  animation: echo-choice-pip var(--echo-duration-pop) var(--echo-ease-pop);
}
.echo-choice-cards__tick {
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: var(--echo-radius-sm);
  color: var(--echo-primary-cap-ink, var(--echo-text));
  background: linear-gradient(180deg, var(--echo-primary-cap-top), var(--echo-primary-cap-base));
}
.echo-choice-cards__tick svg {
  width: var(--echo-icon-sm, 14px);
  height: var(--echo-icon-sm, 14px);
}
.echo-choice-cards__card:has(.echo-choice-cards__tick) .echo-choice-cards__mark {
  border-radius: var(--echo-radius-sm);
}
/* The pip rolls into its hole: it drops in and settles. */
@keyframes echo-choice-pip {
  from {
    transform: scale(0.2);
    opacity: 0;
  }
}
.echo-choice-cards__text {
  display: grid;
  gap: var(--echo-space-2);
  min-width: 0;
}
.echo-choice-cards__title {
  font-size: var(--echo-text-md);
  font-weight: var(--echo-weight-semibold, 600);
}
.echo-choice-cards__description {
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}
.echo-choice-cards__extra {
  margin-top: var(--echo-space-3);
  font-size: var(--echo-text-sm);
  color: var(--echo-text);
}
@media (prefers-reduced-motion: reduce) {
  .echo-choice-cards__card,
  .echo-choice-cards__pip {
    transition: none;
    animation: none;
  }
  .echo-choice-cards__card:active {
    transform: none;
  }
}
@media (forced-colors: active) {
  .echo-choice-cards__card {
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  .echo-choice-cards__card[data-checked] {
    border: var(--echo-border-heavy, 4px) solid Highlight;
  }
  .echo-choice-cards__pip,
  .echo-choice-cards__tick {
    background: Highlight;
  }
}
